/* eslint-disable @typescript-eslint/ban-ts-comment -- the build output may or may not exist when type-checking */
// Worker entry point: requests go to the OpenNext handler, cron ticks to runCronTrigger (by the trigger that fired).
// Both entries check the config first (lib/runtime/config-guard.ts): a refused config answers every request 503
// (withConfigGuard) and skips every cron run (runCron / runCronTrigger record it in job_runs and alert ops).
// `.open-next/worker.js` is generated by `opennextjs-cloudflare build`.
// @ts-ignore: generated at build time
import handler from "./.open-next/worker.js";
import { runCronTrigger } from "./lib/jobs/cron";
import { withConfigGuard } from "./lib/runtime/config-guard";

// Durable Objects OpenNext defines; wrangler needs them exported from the entry point.
// @ts-ignore: generated at build time
export { BucketCachePurge, DOQueueHandler, DOShardedTagCache } from "./.open-next/worker.js";

export default {
  fetch: withConfigGuard<CloudflareEnv, ExecutionContext>((request, env, ctx) => handler.fetch(request, env, ctx)),
  async scheduled(controller: ScheduledController, env: CloudflareEnv, ctx: ExecutionContext) {
    ctx.waitUntil(runCronTrigger(env as never, controller.cron, new Date(controller.scheduledTime)));
  },
} satisfies ExportedHandler<CloudflareEnv>;
